// Checkout conversion module - ensures paidEvents increment on successful checkout
const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function loadRevenue() {
  try {
    if (fs.existsSync(REVENUE_FILE)) {
      return JSON.parse(fs.readFileSync(REVENUE_FILE, 'utf8'));
    }
  } catch (e) {
    console.error('Error loading revenue:', e);
  }
  return { enabled: true, runs: 0, errors: 0, paidEvents: 0, conversionRate: 0, leads: 0 };
}

function saveRevenue(data) {
  fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
}

function recordCheckout(amount) {
  const data = loadRevenue();
  data.paidEvents += 1;
  data.runs += 1;
  data.conversionRate = data.leads > 0 ? (data.paidEvents / data.leads) * 100 : 0;
  saveRevenue(data);
  console.log(`Checkout recorded: paidEvents=${data.paidEvents}, amount=${amount}`);
  return true;
}

function recordLead() {
  const data = loadRevenue();
  data.leads += 1;
  saveRevenue(data);
}

module.exports = { recordCheckout, recordLead, loadRevenue };
